/bin/bash -lc "cd /work && python - <<'PY'
import mujoco
from sim import Sim
sim=Sim(); m=sim.model
print('nsites',m.nsite)
for i in range(m.nsite):
    name=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_SITE,i)
    if name and ('hand' in name or 'grip' in name or 'ee' in name or 'attach' in name):
        print(i,name)
print('nbody',m.nbody)
for i in range(m.nbody):
    name=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_BODY,i)
    if name and ('hand' in name or 'panda' in name or 'finger' in name or 'link' in name):
        if 'panda' in name or 'hand' in name:
            print('body',i,name)
PY"

